import{_ as t,o as r,c as a,a2 as d}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"L1 app development guide","description":"","frontmatter":{},"headers":[],"relativePath":"l1/index.md","filePath":"l1/index.md"}'),o={name:"l1/index.md"};function i(c,e,h,p,s,n){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="l1-app-development-guide" tabindex="-1">L1 app development guide <a class="header-anchor" href="#l1-app-development-guide" aria-label="Permalink to &quot;L1 app development guide&quot;">​</a></h1><p>How to write, build and ship the ring-3 programs of Open Cube OS - from a one-line service wrapper to a full merged mega-app.</p><p>The app model in one paragraph: <strong>one command = one app = one folder</strong> under <code>ocos/l1apps/&lt;name&gt;/</code> holding <code>main.c</code> (+ any extra <code>.c</code>) and <code>i18n/{en,zh}.json</code>. The build discovers folders mechanically (no hand-written tables), compiles each app freestanding against <code>ocos/interface/</code>, and embeds every image into the kernel&#39;s <code>OC_USERPROGS[]</code> registry (284 programs today). At runtime <code>ush</code> forks + execves registry programs by name; apps reach every kernel service through the <code>SYS_L1SVC</code> syscall (category + op + argument line + output buffer).</p><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./overview.html">overview</a></td><td>the app model, the layers, the counts</td></tr><tr><td><a href="./surface-map.html">surface-map</a></td><td>every L1SVC category and op, the syscall bridge</td></tr><tr><td><a href="./app-anatomy.html">app-anatomy</a></td><td>main.c / crt0 / i18n / l1_wizard_api.h - the full anatomy</td></tr><tr><td><a href="./writing-apps.html">writing-apps</a></td><td>a complete app from source to <code>run</code> - tutorial</td></tr><tr><td><a href="./wizard-library.html">wizard-library</a></td><td>the shared wizard primitives behind the 8 mega-apps</td></tr><tr><td><a href="./driver-block.html">driver-block</a></td><td>extending the block service</td></tr><tr><td><a href="./driver-nic.html">driver-nic</a></td><td>extending the NIC service</td></tr><tr><td><a href="./driver-snd.html">driver-snd</a></td><td>extending the sound service</td></tr><tr><td><a href="./ota.html">ota</a></td><td>the OTA/A-B service from the app side</td></tr><tr><td><a href="./solib-loader.html">solib-loader</a></td><td>the in-tree ld.so + ET_DYN programs</td></tr><tr><td><a href="./tui-ext.html">tui-ext</a></td><td>the TUI service surface</td></tr><tr><td><a href="./watchdog-health.html">watchdog-health</a></td><td>watchdog + health from apps</td></tr></tbody></table><h2 id="the-three-doors-every-app-offers" tabindex="-1">The three doors every app offers <a class="header-anchor" href="#the-three-doors-every-app-offers" aria-label="Permalink to &quot;The three doors every app offers&quot;">​</a></h2><p>The 8 merged apps (<code>update</code>, <code>disk-tool</code>, <code>net-tool</code>, <code>sound-tool</code>, <code>files</code>, <code>sysdiag</code>, <code>hwinfo</code>, <code>power</code>) established the three-door contract - no-arg wizard, <code>direct</code> passthrough, classic op dispatch. New apps are free to adopt it; the wizard primitives are one <code>#include &quot;l1_wizard_api.h&quot;</code> away.</p>',6)])])}const f=t(o,[["render",i]]);export{m as __pageData,f as default};
